from itertools import permutations
import z3, time
n=17
edge_index={}
edges=[]
for i in range(n):
 for j in range(i+1,n):
  edge_index[(i,j)]=len(edges); edges.append((i,j))
X=[z3.Bool('e_%d_%d'%e) for e in edges]
def x(i,j):
 if i>j: i,j=j,i
 return X[edge_index[(i,j)]]
cycles=[]
for k in range(3,7):
 for cyc in permutations(range(n),k):
  if cyc[0]!=min(cyc): continue
  if cyc[1]>cyc[-1]: continue
  cycles.append(cyc)
print('cycles', len(cycles), {k:sum(1 for c in cycles if len(c)==k) for k in range(3,7)})
s=z3.Solver()
for cyc in cycles:
 s.add(z3.Not(z3.And([x(cyc[i],cyc[(i+1)%len(cyc)]) for i in range(len(cyc))])))
s.add(z3.PbGe([(v,1) for v in X],30))
colors=[z3.Int('c%d'%i) for i in range(n)]
for c in colors: s.add(c>=0,c<4)
for m,(i,j) in enumerate(edges):
 s.add(z3.Implies(X[m], colors[i]!=colors[j]))
s.set('timeout', 60000)
t=time.time(); res=s.check(); print('res',res,'time',time.time()-t)
if str(res)=='sat':
 model=s.model()
 sol=[]
 for var,e in zip(X,edges):
  if z3.is_true(model.evaluate(var, model_completion=True)):
   sol.append(e)
 print(len(sol), sol)
 print([model.evaluate(c) for c in colors])
